:1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":165,"legada_codigo":"REG_DAT_004","familia":"OFFERS_INSTALLMENTS","diferencias":"Especifica componentes del pago de hoy, separado de total contractual de cuotas."},{"codigo":"S4-C24","eval_id":418,"hash_paquete_atestado":"e276b6c680b2f8d2cc92461803aef3e82d4e15316da23a484e3e175faccd931d","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.8,"observacion":"El cálculo de máximo ahorro y desempate lo efectúa backend; el frontend presenta badge según resultado autorizado."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":240,"legada_codigo":"REG_CUO_006","familia":"OFFERS_INSTALLMENTS","diferencias":"Mantiene desempate del legado sin añadir ponderadores comerciales."},{"codigo":"S4-C25","eval_id":419,"hash_paquete_atestado":"2059ae6e45fae161c4e13b55442ac067ec65e0d8c48d10d28bbcf77bfdc87c7c","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":241,"legada_codigo":"REG_CUO_007","familia":"OFFERS_INSTALLMENTS","diferencias":"Conserva la distinción de copy y porcentaje legado; cálculo de ahorro es backend."}]'::jsonb) LOOP
  cd:=p->>'codigo';
  SELECT id,hash_paquete,decision INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=1 ORDER BY id DESC LIMIT 1;
  IF e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado'
   OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::int)
   OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA')
  THEN RAISE EXCEPTION 'S4_EVAL_VERSION_DRIFT %',cd; END IF;
  h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
  IF h IS DISTINCT FROM p->>'hash_paquete_atestado' THEN RAISE EXCEPTION 'S4_PACKAGE_CHANGED %',cd; END IF;
  v:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto',
   'puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE',
   'revisor_es_productor',false,'llamadas_modelo',1,
   'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s4_juicios_independientes_v1.json#'||cd);
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(v||jsonb_build_object('hash_evaluado',repeat('0',64)));
   RAISE EXCEPTION 'S4_HASH_NEGATIVE_ACCEPTED %',cd;
  EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
  PERFORM lf_ops.nucleo_juicio_registrar_v1(v);
  result:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF cd='S4-C04' THEN
   IF p->>'veredicto'<>'DEVOLVER' OR result->>'decision'='AUTO' THEN RAISE EXCEPTION 'S4_C04_NOT_RETURNED'; END IF;
   pending:=pending+1;
  ELSIF cd='S4-C17' THEN
   IF p->>'veredicto'<>'DEVOLVER' OR result->>'decision'='AUTO' THEN RAISE EXCEPTION 'S4_C17_NOT_RETURNED'; END IF;
   PERFORM lf_ops.nucleo_version_descartar_v1(cd,'LEG-TECNICO','DEVOLVER Claude por duplicidad de flujo celular-first con S4-C02/C03; versión descartada sin tocar legada 455');
   discarded:=discarded+1;
  ELSIF result->>'decision'='AUTO' THEN
   v:=lf_ops.nucleo_regla_promover_v1(cd);
   IF v->>'resultado'<>'PROMOVIDA_AUTO' OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)<>'PUBLICADA'
   THEN RAISE EXCEPTION 'S4_AUTO_PROMOTION_FAIL % %',cd,v; END IF;
   aut:=aut+1;
  ELSE RAISE EXCEPTION 'S4_NON_AUTO_UNEXPECTED % %',cd,result; END IF;
  n:=n+1;
  RAISE NOTICE 'S4_JUDGE % verdict=% decision=% nota=%',cd,p->>'veredicto',result->>'decision',result->>'nota';
 END LOOP;
 IF n<>25 OR aut<>23 OR pending<>1 OR discarded<>1
  OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S4-C%')<>25
  OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S4-C%' AND estado='CANDIDATA')<>1
  OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S4-C%' AND estado='DESCARTADA')<>1
  OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM prev_legacy
  OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM prev_deprec
 THEN RAISE EXCEPTION 'S4_JUDGEMENT_FINAL_FAIL'; END IF;
 RAISE NOTICE 'S4_JUDGEMENTS_PASS 25_JUZGADAS 23_AUTO 1_CANDIDATA 1_DESCARTADA';
END $judge$;
