,"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":242,"legada_codigo":"REG_MOD_003","familia":"TRANSITIONS","diferencias":"El límite de latencia es configurable, no se replica cifra de implementación."},{"codigo":"S4-C14","eval_id":408,"hash_paquete_atestado":"11c57096018f1887596e268366f2f30c8cab37b101976d498e2769808c3c6cc6","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":243,"legada_codigo":"REG_MOD_004","familia":"TRANSITIONS","diferencias":"Explicita preservar estado previo frente a vista provisional de planes."},{"codigo":"S4-C15","eval_id":409,"hash_paquete_atestado":"ba916d01158b94f2d10cb2abef1d12cc0b3e592a4ab5447a7ff781310abdb906","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":261,"legada_codigo":"REG_CUO_011","familia":"TRANSITIONS","diferencias":"Vincula enlace a plan activo, evita referencias obsoletas y no inventa destino."},{"codigo":"S4-C16","eval_id":410,"hash_paquete_atestado":"db56ac0c3772bc620076f28262fed13cbbc3bacec3e8ed87c2cb66ef475fed2a","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":262,"legada_codigo":"REG_CUO_012","familia":"TRANSITIONS","diferencias":"Plan/fecha quedan congelados para checkout; no crea cálculo nuevo de cuotas."},{"codigo":"S4-C17","eval_id":411,"hash_paquete_atestado":"962664a9d9ea19463f8d2ec8ecd74031300bab580703119e6b34d2742bc26ed2","version":1,"veredicto":"DEVOLVER","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.4,"observacion":"Repite requisitos de C02 (celular previo a perfil) y C03 (ONB_003 solo después de OTP); devolver y descartar."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":455,"legada_codigo":"REG_FLOW_CELL_FIRST_001","familia":"TRANSITIONS","diferencias":"Reafirma celular-first del legado sin crear campos ni pasos nuevos."},{"codigo":"S4-C18","eval_id":412,"hash_paquete_atestado":"3ecde02350ea976ce1b0127689d949d89e578774a3d91e295c9ef3d76679f140","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":0.9,"observacion":"Mezcla rama de acceso y alta de nuevo cliente; backend debe distinguir ambas sin inferencia UI."},"SEM_NO_DUPLICA":{"puntaje":0.7,"observacion":"Comparte predicados con C03 y C19; C18 resuelve rama server-side, C19 exige datos de compleción."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":457,"legada_codigo":"REG_FLOW_PHONE_BRANCH_001","familia":"TRANSITIONS","diferencias":"Resume ramas y condiciones exactas de legado; no inventa contratos de endpoints."},{"codigo":"S4-C19","eval_id":413,"hash_paquete_atestado":"194e462dffaa0077ee4ba3ecc80b3331d4b2a0d0988c71c3184e55ef6a4db2f1","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Exigencia de consentimientos coincide parcialmente con C07; C19 cubre submit atómico de NEW_CLIENT_DATA_COMPLETION."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":504,"legada_codigo":"REG_NEW_CLIENT_COMPLETION_SUBMIT_001","familia":"TRANSITIONS","diferencias":"No se inventan reglas de formato: campo correo validado por las políticas ya vigentes."},{"codigo":"S4-C20","eval_id":414,"hash_paquete_atestado":"922e65e5d5a0a6197feee0b7a97c3a3fe5cd642e703cae056eacebabba14921f","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.9,"observacion":"No se identifican aún destinos Cliente canónicos; el control es deshabilitar navegación no aprobada."},"CAL_ACCIONABLE":{"puntaje":0.8,"observacion":"Los destinos Cliente todavía no están definidos; regla solo permite bloquear, no construir rutas."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":488,"legada_codigo":"REG_ONB002_NAVIGATION_001","familia":"TRANSITIONS","diferencias":"Alcance solo ONB_002, no crea URLs."},{"codigo":"S4-C21","eval_id":415,"hash_paquete_atestado":"d81bb1aae16f24d3199916151cc0b976f308b19e181d86091e84d4b4524140b4","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":141,"legada_codigo":"REG_HMV_001","familia":"OFFERS_INSTALLMENTS","diferencias":"La ausencia de ofertas exige consulta autoritativa exitosa; no inferir sin oferta por timeout."},{"codigo":"S4-C22","eval_id":416,"hash_paquete_atestado":"17826f62a7c8de591e369f62998f32dc001cb7a508580805d527708fac808706","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.7,"observacion":"Texto dice no bloquear cuotas mayores que contado, pero efecto BLOQUEAR solo aplica a UI que fuerza total cuotas igual o menor."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":0.8,"observacion":"El hecho agregado de violación representa intento de forzar cuotas menores/iguales; requiere aclaración en posible v2."},"COH_EFECTO":{"puntaje":1}},"legada_id":151,"legada_codigo":"REG_OFR_006","familia":"OFFERS_INSTALLMENTS","diferencias":"La intención es permitir diferencia financiera legítima, no definir tasa de interés."},{"codigo":"S4-C23","eval_id":417,"hash_paquete_atestado":"02fb08b681c8d3fc8db2b14c08e26293d550e806aea6b78ad10c4b7c65c99222","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":165,"legada_codigo":"REG_DAT_004","familia":"OFFERS_INSTALLMENTS","diferencias":"Especifica componentes del pago de hoy, separado de total contractual de cuotas."},{"codigo":"S4-C24","eval_id":418,"hash_paquete_atestado":"e276b6c680b2f8d2cc92461803aef3e82d4e15316da23a484e3e175faccd931d","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.8,"observacion":"El cálculo de máximo ahorro y desempate lo efectúa backend; el frontend presenta badge según resultado autorizado."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":240,"legada_codigo":"REG_CUO_006","familia":"OFFERS_INSTALLMENTS","diferencias":"Mantiene desempate del legado sin añadir ponderadores comerciales."},{"codigo":"S4-C25","eval_id":419,"hash_paquete_atestado":"2059ae6e45fae161c4e13b55442ac067ec65e0d8c48d10d28bbcf77bfdc87c7c","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:44 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":241,"legada_codigo":"REG_CUO_007","familia":"OFFERS_INSTALLMENTS","diferencias":"Conserva la distinción de copy y porcentaje legado; cálculo de ahorro es backend."}]'::jsonb) LOOP
  v_code:=p->>'codigo';id0:=(p->>'legada_id')::int;
  IF v_code IN ('S4-C04','S4-C17') THEN CONTINUE; END IF;
  -- PG17 aislado contiene corpus legadas parcial; FK no puede exigir filas ausentes.
  -- En la base real (586) todas las 23 fuentes deben existir.
  IF NOT EXISTS (SELECT 1 FROM lf_ops.reglas WHERE id=id0) THEN
   IF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S4_LEGACY_MISSING_IN_REAL %',id0; END IF;
   RAISE NOTICE 'S4_PG17_FIXTURE_LEGACY_ABSENT %',id0;
   CONTINUE;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=v_code AND version=1 AND estado='PUBLICADA')
  THEN RAISE EXCEPTION 'S4_UNPUBLISHED_COVERAGE %',v_code; END IF;
  hp:=lf_ops.nucleo_hash_paquete_v1(v_code,1);
  status:='REEMPLAZADA';resid:='';
  d:=CASE WHEN v_code='S4-C22' THEN 'La legada REG_OFR_006 permite total cuotas mayor al contado. S4-C22 BLOQUEA únicamente la UI que fuerza total cuotas menor o igual, no bloquea el plan legítimamente mayor. Cálculo y precio autorizados por backend.'
     WHEN v_code='S4-C24' THEN 'REG_CUO_006 exige badge Recomendado por máximo ahorro absoluto; empate por menor primera cuota y un badge por modal. El cálculo es de backend, el frontend solo presenta resultado autorizado, elimina Popular.'
     WHEN v_code='S4-C25' THEN 'REG_CUO_007 exige copy literal Ahorras S/ X (Y%) para ahorro positivo y Sin descuento adicional cuando no hay ahorro, sin negativos; backend calcula el ahorro y UI presenta.'
     ELSE p->>'diferencias' END;
  INSERT INTO lf_ops.lf_nucleo_cobertura_legada
  (legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
  VALUES (id0,v_code,1,status,d,
    jsonb_build_object('fuente','lf_ops.v_reglas_compat_v1/'||id0||' '||(p->>'legada_codigo'),
     'contraste','LEGADA: '||COALESCE((SELECT descripcion FROM lf_ops.v_reglas_compat_v1 WHERE id=id0),'[Fuente legada ausente solo en fixture PG17 id '||id0||']')
       ||' NUCLEO: '||COALESCE((SELECT descripcion FROM lf_ops.nucleo_regla_versiones WHERE regla=v_code AND version=1),'[Descripción de paquete publicada no presente en fixture]')
       ||' DIFERENCIAS: '||COALESCE(d,'[Sin diferencias adicionales verificadas]'),
     'residual',resid,'juicio','Claude independiente S4 2026-11-23 21:44'),
    hp,'GPT-6 / Claude S4 con juicio independiente');
  n:=n+1;
 END LOOP;
 -- C17 rechazado corresponde a LEGADA 455; C02 y C03 cubren parte, pero NO aseguran que ONB_001
 -- solicite exclusivamente celular. Puente PARCIAL, sin inventar cobertura total.
 FOR v_code IN SELECT unnest(ARRAY['S4-C02','S4-C03']) LOOP
  IF NOT EXISTS (SELECT 1 FROM lf_ops.reglas WHERE id=455) THEN
   IF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S4_LEGACY455_MISSING_REAL'; END IF;
   RAISE NOTICE 'S4_PG17_FIXTURE_LEGACY455_ABSENT';
   EXIT;
  END IF;
  resid:='REG_FLOW_CELL_FIRST_001 exige que ONB_001 solicite exclusivamente celular como primer dato; S4-C02 valida ONB_002 y S4-C03 valida ONB_003, pero ninguna norma directamente el formulario de ONB_001. Requiere nueva candidata específica o prueba de cobertura publicada.';
  d:=CASE WHEN v_code='S4-C02' THEN 'La canónica S4-C02 exige phone_number y OTP antes de ONB_002, sin datos de perfil; no obliga exclusivamente celular en ONB_001.' ELSE 'S4-C03 prohíbe ONB_003 antes del OTP y resuelve la cuenta reconocida; no obliga exclusivamente celular en ONB_001.' END;
  hp:=lf_ops.nucleo_hash_paquete_v1(v_code,1);
  INSERT INTO lf_ops.lf_nucleo_cobertura_legada
  (legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
  VALUES(455,v_code,1,'PARCIAL',d,jsonb_build_object('fuente','lf_ops.v_reglas_compat_v1/455 REG_FLOW_CELL_FIRST_001','contraste',d,'residual',resid,'juicio','Claude S4 C17 DEVOLVER por duplicación'),hp,'GPT-6/CLaude S4 semántica conservadora');
  partial_n:=partial_n+1;
 END LOOP;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND (n<>23 OR partial_n<>2))
  OR (SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>(75+n)
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>before_deprec
  OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM before_legadas
 THEN RAISE EXCEPTION 'S4_BRIDGE_INVALID'; END IF;
 RAISE NOTICE 'S4_BRIDGE_PASS nuevos_reemplazos=23 parcial_455=2 vinculos';
END $bridge$;
COMMIT;
